const items = $input.all();
const loopData = $('Loop Events').first().json;
const eventLink = loopData.eventLink;
const eventText = loopData.eventText;

if (items.length === 0 || !items[0].json.id) {
  // Event does not exist - is new
  return [{ json: { eventLink, eventText, exists: false } }];
} else {
  // Event exists
  return [{ json: { ...items[0].json, exists: true } }];
}

try {
  const html = $input.first().json.data;
  const loopData = $('Loop Events').first().json;
  const eventLink = loopData.eventLink;
  const eventText = loopData.eventText;

  if (!html || typeof html !== 'string') {
    throw new Error('Invalid HTML input');
  }

  // Convert HTML to simplified markdown
  let content = html;

  // Remove scripts and styles
  content = content.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  content = content.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');

  // Remove HTML comments
  content = content.replace(/<!--[\s\S]*?-->/g, '');

  // Convert common elements to markdown
  content = content.replace(/<h1[^>]*>(.*?)<\/h1>/gi, '\n# $1\n');
  content = content.replace(/<h2[^>]*>(.*?)<\/h2>/gi, '\n## $1\n');
  content = content.replace(/<h3[^>]*>(.*?)<\/h3>/gi, '\n### $1\n');
  content = content.replace(/<p[^>]*>(.*?)<\/p>/gi, '\n$1\n');
  content = content.replace(/<br\s*\/?>/gi, '\n');
  content = content.replace(/<li[^>]*>(.*?)<\/li>/gi, '- $1\n');
  content = content.replace(/<strong[^>]*>(.*?)<\/strong>/gi, '**$1**');
  content = content.replace(/<b[^>]*>(.*?)<\/b>/gi, '**$1**');
  content = content.replace(/<em[^>]*>(.*?)<\/em>/gi, '*$1*');
  content = content.replace(/<i[^>]*>(.*?)<\/i>/gi, '*$1*');

  // Remove remaining HTML tags
  content = content.replace(/<[^>]+>/g, '');

  // Clean up whitespace
  content = content.replace(/&nbsp;/g, ' ');
  content = content.replace(/&amp;/g, '&');
  content = content.replace(/&lt;/g, '<');
  content = content.replace(/&gt;/g, '>');
  content = content.replace(/\n\s*\n\s*\n/g, '\n\n');
  content = content.trim();

  // Limit content length for LLM
  if (content.length > 8000) {
    content = content.substring(0, 8000) + '...';
  }

  return [{ json: { url: eventLink, calendarText: eventText, markdown: content } }];
} catch (error) {
  throw new Error(`HTML to Markdown conversion failed: ${error.message}`);
}

